package com.cekalix.controlador;
import com.cekalix.dao.*;import com.cekalix.modelo.*;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/ventas")
public class VentaServlet extends HttpServlet {private final VentaDAO vd=new VentaDAO();private final ClienteDAO cd=new ClienteDAO();private final ProductoDAO pd=new ProductoDAO();
protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("ventas",vd.listar());q.setAttribute("clientes",cd.listar());q.setAttribute("productos",pd.listar());q.getRequestDispatcher("/WEB-INF/vistas/ventas.jsp").forward(q,p);}catch(SQLException e){throw new ServletException(e);}}
protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{Usuario u=(Usuario)q.getSession().getAttribute("usuarioSesion");String[] a=q.getParameterValues("productoId"),b=q.getParameterValues("cantidad");if(a==null||b==null||a.length!=b.length)throw new SQLException("Agrega al menos un producto.");int[] ids=new int[a.length],cant=new int[b.length];for(int i=0;i<a.length;i++){ids[i]=Integer.parseInt(a[i]);cant[i]=Integer.parseInt(b[i]);}int id=vd.registrar(Integer.parseInt(q.getParameter("clienteId")),u.getIdUsuario(),q.getParameter("tipoComprobante"),q.getParameter("metodoPago"),ids,cant);q.getSession().setAttribute("mensaje","Venta interna #"+id+" registrada.");p.sendRedirect(q.getContextPath()+"/ventas");}catch(Exception e){q.getSession().setAttribute("error",e.getMessage());p.sendRedirect(q.getContextPath()+"/ventas");}}}